import{_ as i,o as t,c as o,ae as a}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"Remediation UI, Recovery Suppression, and Tests","description":"","frontmatter":{"work_package_id":"WP02","title":"Remediation UI, Recovery Suppression, and Tests","lane":"done","dependencies":["WP01"],"base_branch":"015-lane-orphan-detection-and-remediation-WP01","base_commit":"f89fa0e1acc75074dedcfee0d26f175325c18ba1","created_at":"2026-03-01T13:32:33.216956+00:00","subtasks":["T007","T008","T009","T010","T011"],"phase":"Phase 2 - Remediation and Hardening","assignee":"","agent":"claude-haiku","shell_pid":"67031","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/015-lane-orphan-detection-and-remediation/tasks/WP02-remediation-ui-and-recovery-suppression.md","filePath":"specs/015-lane-orphan-detection-and-remediation/tasks/WP02-remediation-ui-and-recovery-suppression.md"}'),s={name:"specs/015-lane-orphan-detection-and-remediation/tasks/WP02-remediation-ui-and-recovery-suppression.md"};function n(r,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="work-package-prompt-wp02-remediation-ui-recovery-suppression-and-tests" tabindex="-1">Work Package Prompt: WP02 - Remediation UI, Recovery Suppression, and Tests <a class="header-anchor" href="#work-package-prompt-wp02-remediation-ui-recovery-suppression-and-tests" aria-label="Permalink to &quot;Work Package Prompt: WP02 - Remediation UI, Recovery Suppression, and Tests&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement user-facing remediation suggestions with confirmation gates (no automatic cleanup).</li><li>Implement cleanup actions: worktree metadata snapshot + deletion, graceful PTY termination, zellij session kill.</li><li>Implement recovery-aware suppression and declined-cleanup cooldown.</li><li>Emit detection and remediation lifecycle events on the internal bus.</li><li>Deliver comprehensive integration tests including false-positive rate validation.</li></ul><p>Success criteria:</p><ul><li>Zero resources cleaned up without explicit user confirmation.</li><li>Cleanup suggestions suppressed for resources involved in active recovery.</li><li>Declined cleanups enter cooldown and are not re-suggested until cooldown expires.</li><li>Cleanup failures are reported and skipped without halting remaining actions.</li><li>False-positive rate below 1% across 500+ detection cycles.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/015-lane-orphan-detection-and-remediation/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/015-lane-orphan-detection-and-remediation/spec.md</code></li><li>Watchdog and detectors: <code>apps/runtime/src/lanes/watchdog/</code> (WP01)</li><li>Resource classifier: <code>apps/runtime/src/lanes/watchdog/resource_classifier.ts</code> (WP01)</li><li>Internal event bus: <code>apps/runtime/src/protocol/bus.ts</code> (spec 001)</li></ul><p>Constraints:</p><ul><li>Never execute cleanup without user confirmation.</li><li>Keep files under 500 lines.</li><li>TypeScript + Bun runtime.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP02</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t007-implement-remediation-suggestion-engine-with-confirmation-gates" tabindex="-1">Subtask T007 - Implement remediation suggestion engine with confirmation gates <a class="header-anchor" href="#subtask-t007-implement-remediation-suggestion-engine-with-confirmation-gates" aria-label="Permalink to &quot;Subtask T007 - Implement remediation suggestion engine with confirmation gates&quot;">​</a></h3><ul><li>Purpose: present cleanup suggestions to the user and require explicit confirmation before any action.</li><li>Steps: <ol><li>Implement <code>RemediationEngine</code> in <code>apps/runtime/src/lanes/watchdog/remediation.ts</code>: a. Accept classified orphan list from the watchdog cycle. b. Generate <code>RemediationSuggestion</code> objects: i. Resource details (type, path/PID, age, risk level, estimated owner). ii. Suggested action (delete worktree, kill zellij session, terminate PTY process). iii. Confirmation requirement flag (always true in slice-1). c. Expose <code>getSuggestions(): RemediationSuggestion[]</code> for the UI to display. d. Expose <code>confirmCleanup(suggestionId): Promise&lt;CleanupResult&gt;</code> that executes only after confirmation. e. Expose <code>declineCleanup(suggestionId): void</code> that marks the resource for cooldown.</li><li>Implement suggestion lifecycle: a. New suggestions are created after each watchdog cycle. b. Confirmed suggestions trigger cleanup execution (T008). c. Declined suggestions enter cooldown (T009). d. Stale suggestions (resource no longer orphaned) are auto-removed.</li><li>Return structured results for each cleanup attempt (success, failure with reason).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/lanes/watchdog/remediation.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: generate suggestions from classified orphans, verify all have confirmation required.</li><li>Unit test: confirm cleanup, verify action executed.</li><li>Unit test: decline cleanup, verify cooldown applied.</li><li>Unit test: verify no cleanup executes without explicit <code>confirmCleanup</code> call.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t008-implement-cleanup-actions" tabindex="-1">Subtask T008 - Implement cleanup actions <a class="header-anchor" href="#subtask-t008-implement-cleanup-actions" aria-label="Permalink to &quot;Subtask T008 - Implement cleanup actions&quot;">​</a></h3><ul><li>Purpose: execute safe cleanup for each resource type after user confirmation.</li><li>Steps: <ol><li>Implement worktree cleanup in <code>apps/runtime/src/lanes/watchdog/remediation.ts</code> or a sub-module: a. Before deletion: take a lightweight metadata snapshot (branch, HEAD commit, modified files list) and store in <code>~/.helios/data/worktree_snapshots/</code>. b. Delete the worktree directory using <code>git worktree remove</code> or filesystem removal. c. Retain snapshot for a configurable retention period (default: 7 days).</li><li>Implement PTY process cleanup: a. Send SIGTERM to the process. b. Wait up to 5 seconds for graceful exit. c. If still alive, send SIGKILL. d. Record termination result.</li><li>Implement zellij session cleanup: a. Kill the zellij session using <code>zellij kill-session &lt;name&gt;</code>. b. Verify session is no longer listed.</li><li>Handle cleanup failures: a. If any cleanup fails (e.g., permission denied), record the failure reason. b. Skip the failed resource and continue with remaining cleanups. c. Return per-resource results to the caller.</li><li>All cleanup actions must be idempotent (safe to retry).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/lanes/watchdog/remediation.ts</code></li></ul></li><li>Validation: <ul><li>Integration test: create orphaned worktree, confirm cleanup, verify worktree removed and snapshot saved.</li><li>Integration test: spawn orphaned PTY process, confirm cleanup, verify process terminated.</li><li>Unit test: simulate cleanup failure, verify skip + error reporting.</li><li>Unit test: verify snapshot retention creates recoverable metadata.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t009-implement-recovery-aware-suppression-and-declined-cleanup-cooldown" tabindex="-1">Subtask T009 - Implement recovery-aware suppression and declined-cleanup cooldown <a class="header-anchor" href="#subtask-t009-implement-recovery-aware-suppression-and-declined-cleanup-cooldown" aria-label="Permalink to &quot;Subtask T009 - Implement recovery-aware suppression and declined-cleanup cooldown&quot;">​</a></h3><ul><li>Purpose: prevent false cleanup suggestions for recovering resources and honor user decline decisions.</li><li>Steps: <ol><li>Implement recovery-aware suppression: a. Before generating suggestions, cross-reference orphan candidates against active recovery operations. b. Query the lane/session registry for lanes in <code>recovering</code> state. c. Exclude any orphan whose estimated owner is a recovering lane. d. Log suppression decisions for debugging.</li><li>Implement declined-cleanup cooldown: a. Maintain a cooldown map: <code>Map&lt;resourceKey, cooldownExpiresAt&gt;</code>. b. When <code>declineCleanup</code> is called, add resource to cooldown with configurable duration (default: 24 hours). c. During suggestion generation, exclude resources in active cooldown. d. Persist cooldown map to disk for restart survival.</li><li>Implement cooldown expiry: remove expired entries on each detection cycle.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/lanes/watchdog/remediation.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: orphan with recovering lane owner, verify suppressed from suggestions.</li><li>Unit test: decline cleanup, verify resource excluded from next cycle suggestions.</li><li>Unit test: cooldown expires, verify resource re-appears in suggestions.</li><li>Integration test: persist cooldown, restart, verify cooldown still active.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t010-wire-detection-and-remediation-events-on-the-internal-bus" tabindex="-1">Subtask T010 - Wire detection and remediation events on the internal bus <a class="header-anchor" href="#subtask-t010-wire-detection-and-remediation-events-on-the-internal-bus" aria-label="Permalink to &quot;Subtask T010 - Wire detection and remediation events on the internal bus&quot;">​</a></h3><ul><li>Purpose: enable downstream consumers (UI, audit, monitoring) to react to orphan detection and remediation actions.</li><li>Steps: <ol><li>Define event topics: a. <code>orphan.detection.cycle_completed</code>: emitted after each watchdog cycle with summary. b. <code>orphan.detection.resource_found</code>: emitted for each newly detected orphan. c. <code>orphan.remediation.suggested</code>: emitted when suggestions are generated. d. <code>orphan.remediation.confirmed</code>: emitted when user confirms a cleanup. e. <code>orphan.remediation.completed</code>: emitted after cleanup execution (success or failure). f. <code>orphan.remediation.declined</code>: emitted when user declines a cleanup.</li><li>Define event payloads with resource details, action, result, and correlation IDs.</li><li>Wire events into the watchdog, remediation engine, and cleanup actions.</li><li>Register topics in the protocol topic registry.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/lanes/watchdog/orphan_watchdog.ts</code> (cycle events)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/lanes/watchdog/remediation.ts</code> (remediation events)</li></ul></li><li>Validation: <ul><li>Unit test: run detection cycle, verify <code>cycle_completed</code> event emitted with correct counts.</li><li>Unit test: confirm cleanup, verify <code>confirmed</code> and <code>completed</code> events emitted.</li><li>Unit test: decline cleanup, verify <code>declined</code> event emitted.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t011-add-integration-tests" tabindex="-1">Subtask T011 - Add integration tests <a class="header-anchor" href="#subtask-t011-add-integration-tests" aria-label="Permalink to &quot;Subtask T011 - Add integration tests&quot;">​</a></h3><ul><li>Purpose: validate the complete orphan detection and remediation workflow under realistic conditions.</li><li>Steps: <ol><li>Create <code>apps/runtime/tests/integration/lanes/watchdog/detection_accuracy.test.ts</code>: a. Create a mixed environment with active lanes, orphaned worktrees, stale zellij sessions, and leaked PTY processes. b. Run 2 watchdog cycles and verify all orphans detected with correct classification. c. Verify no false positives for active resources.</li><li>Create <code>apps/runtime/tests/integration/lanes/watchdog/remediation_workflow.test.ts</code>: a. Test full workflow: detect -&gt; suggest -&gt; confirm -&gt; cleanup for each resource type. b. Test decline -&gt; cooldown -&gt; re-detection after cooldown expires. c. Test cleanup failure handling: inject permission error, verify skip + continue.</li><li>Create <code>apps/runtime/tests/integration/lanes/watchdog/recovery_suppression.test.ts</code>: a. Create orphan whose lane is recovering, verify suppressed. b. Complete recovery, verify orphan detected on next cycle.</li><li>Create <code>apps/runtime/tests/integration/lanes/watchdog/false_positive_rate.test.ts</code>: a. Create healthy system with 50 active lanes and no orphans. b. Run 500+ detection cycles. c. Assert zero false positives (or &lt;1% rate).</li><li>Create <code>apps/runtime/tests/integration/lanes/watchdog/performance.test.ts</code>: a. Create 100 lane mock environment with 20 orphans. b. Measure detection cycle time, assert &lt;2 seconds.</li><li>Aim for &gt;=85% line coverage across all watchdog modules.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/lanes/watchdog/detection_accuracy.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/lanes/watchdog/remediation_workflow.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/lanes/watchdog/recovery_suppression.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/lanes/watchdog/false_positive_rate.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/lanes/watchdog/performance.test.ts</code></li></ul></li><li>Parallel: Yes (after T007-T010 are implemented).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Integration tests with simulated orphan environments.</li><li>False-positive rate validation across 500+ detection cycles.</li><li>Performance benchmarks for detection cycle timing.</li><li>Cleanup verification with real filesystem and process operations (in test sandbox).</li><li>Aim for &gt;=85% line coverage.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: cleanup of recovering resource due to race condition.</li><li>Mitigation: recovery-aware suppression and two-cycle confirmation requirement.</li><li>Risk: cooldown map grows unbounded.</li><li>Mitigation: expire and prune entries on each cycle.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm no cleanup path executes without explicit user confirmation.</li><li>Confirm recovery-aware suppression cross-references current lane/session state.</li><li>Confirm cooldown persistence survives restart.</li><li>Confirm cleanup failures are handled gracefully (skip + continue).</li><li>Confirm false-positive rate test uses sufficient iterations.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z -- system -- lane=planned -- Prompt created.</li><li>2026-03-01T13:32:33Z – claude-haiku – shell_pid=67031 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:34:21Z – claude-haiku – shell_pid=67031 – lane=done – Implemented remediation engine and integration tests</li></ul>',30)])])}const h=i(s,[["render",n]]);export{m as __pageData,h as default};
